INSERT INTO zc_private.discord_watch(discord_id,kind,target_id) VALUES($1,$2,$3) ON CONFLICT(discord_id,kind,target_id) DO UPDATE SET paused=false,last_error=NULL, date_updated=clock_timestamp() RETURNING id,discord_id,kind,target_id,paused,last_error, last_delivery_key,to_char(date_created AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS date_created,to_char(date_updated AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS date_updated
